import numpy as np
def rings(F,g):
    return [(F['r0'],b_) for b_ in range(F['c0'],F['c1']+1)]+[(F['r1'],b_) for b_ in range(F['c0'],F['c1']+1)]+[(a_,F['c0']) for a_ in range(F['r0'],F['r1']+1)]+[(a_,F['c1']) for a_ in range(F['r0'],F['r1']+1)]

def solve(g_in):
    g=np.array(g_in); H,W=g.shape
    res=g.copy()
    # detect frames: maximal axis-aligned rects of uniform non-zero color with closed border
    frames=[]
    seen=np.zeros_like(g,bool)
    for i in range(H):
        for j in range(W):
            if g[i,j]==0 or seen[i,j]: continue
            col=int(g[i,j]); q=[(i,j)]; seen[i,j]=True; cells=set()
            while q:
                a,b=q.pop(); cells.add((a,b))
                for da in(-1,0,1):
                    for db in(-1,0,1):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x,y] and g[x,y]==col:
                            seen[x,y]=True;q.append((x,y))
            rs=[a for a,_ in cells]; cs=[b for _,b in cells]
            r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
            h,w=r1-r0+1,c1-c0+1
            rc=rings({'r0':r0,'r1':r1,'c0':c0,'c1':c1},g)
            if len(cells)==len(rc) and all(g[a,b]==col for a,b in rc):
                inner=[(a,b) for a in range(r0+1,r1) for b in range(c0+1,c1)]
                nz=sum(1 for a,b in inner if g[a,b]!=0)
                if max(h,w)>=3 and ((h*w-nz*2)//(h*w))>=0.6:  # interior mostly empty
                    frames.append({'r0':r0,'r1':r1,'c0':c0,'c1':c1,'col':col,'cells':cells})
    noise=[(a,b,int(g[a,b])) for a in range(H) for b in range(W)]
    for F in frames:
        # distance from each noise dot to frame rect bbox
        def dbox(a,b,F):
            return max(max(F['r0']-a,a-F['r1']),max(F['c0']-b,b-F['c1']))
        best=min(((dbox(a,b,F_),v,(a,b)) for a,b,v in noise),key=lambda t:(t[0],t[1]))
        fc=best[1]
        par=(F['r0']+F['c0'])%2
        for a in range(F['r0']+1,F['r1']):
            for b in range(F['c0']+1,F['c1']):
                if res[a,b]==0 and (a+b)%2==par:
                    res[a,b]=fc
        # clear noise not part of any frame
        fr_cells=set().union(*[F['cells'] for F in frames]) if frames else set()
        for a,b in [(i,j) for i in range(H) for j in range(W)]:
            if g[a,b]!=0 and (a,b) not in fr_cells:
                res[a,b]=0
    return res.tolist()

