            if v!=0 and v not in bc and (a_,b_) not in inside: bycol.setdefault(v,[]).append((a_,b_))
    frs=sorted(fr,key=lambda F:(F[2]-F[0]-1)*(F[3]-F[1]-1),reverse=True)
    colors=sorted(bycol.items(),key=lambda kv:-len(kv[1]))
